void sirala5(int *g) {                 /* 5 elemanli insertion sort */
    for (int i = 1; i < 5; i++) {
        int x = g[i], j = i - 1;
        while (j >= 0 && g[j] > x) { g[j+1] = g[j]; j--; }
        g[j+1] = x;
    }
